engine.kernelCheckParse:
function kernelCheckParse(raw) {
  // Returns null when the payload can't be trusted. A half-written marker
  // must not be able to trigger an update notice.
  if (!raw || typeof raw !== "object") return null;
  var v = typeof raw.version === "string" ? raw.version.trim() : "";
  var url = typeof raw.importUrl === "string" ? raw.importUrl.trim() : "";
  if (!v) return null;
  if (!/^https:\/\//i.test(url)) return null;
  return {
    version: v,
    importUrl: url,
    builtAt: typeof raw.builtAt === "string" ? raw.builtAt : "",
    bytes: isFinite(Number(raw.bytes)) ? Number(raw.bytes) : 0,
    notes: typeof raw.notes === "string" ? raw.notes : "",
    // [{name, role}] — who to ask. Entries missing a name are dropped so a
    // half-filled marker can't render an empty bullet.
    adminContacts: Array.isArray(raw.adminContacts)
      ? raw.adminContacts.map(function (c) {
          if (typeof c === "string") return { name: c.trim(), role: "" };
          if (!c || typeof c !== "object") return null;
          return { name: String(c.name || "").trim(), role: String(c.role || "").trim() };
        }).filter(function (c) { return c && c.name; })
      : [],
  };
}

engine.kernelCheckCompare:
function kernelCheckCompare(current, latest) {
  // → { state: "current" | "behind" | "ahead" | "unknown", reason }
  // Only "behind" is actionable. Everything else stays silent: a wrong
  // "you're out of date" costs more trust than a missed one.
  function _stamp(s) {
    var m = /^v3-(\d{4})-(\d{2})-(\d{2})/.exec(String(s || ""));
    return m ? (m[1] + m[2] + m[3]) : null;
  }
  var cur = String(current == null ? "" : current).trim();
  var lat = (latest && latest.version) ? String(latest.version).trim() : "";
  if (!lat) return { state: "unknown", reason: "nothing published" };
  if (!cur) return { state: "unknown", reason: "kernel reports no version" };
  if (cur === lat) return { state: "current", reason: "exact match" };

  var ld = _stamp(lat);
  if (!ld) return { state: "unknown", reason: "published version unparseable" };
  var cd = _stamp(cur);
  // A kernel whose version predates the stamped format is by definition
  // older than anything published under it.
  if (!cd) return { state: "behind", reason: "unstamped kernel" };
  if (cd > ld) return { state: "ahead", reason: "local build newer than published" };
  if (cd < ld) return { state: "behind", reason: "older build date" };
  // Same date, different content hash — a rebuild on the same day.
  return { state: "behind", reason: "same day, newer build" };
}

engine.kernelCheckAge:
function kernelCheckAge(builtAt, now) {
  // Whole days between the published build and now. -1 when unknowable,
  // so the caller can omit the phrase rather than print "0 days behind".
  var t = Date.parse(String(builtAt || ""));
  if (!isFinite(t)) return -1;
  var n = isFinite(Number(now)) ? Number(now) : Date.now();
  var days = Math.floor((n - t) / 86400000);
  return days < 0 ? -1 : days;
}

view.renderKernelUpdate:
function renderKernelUpdate(opts) {
  opts = opts || {};
  var latest = opts.latest || {};
  var current = opts.current || "unknown";
  var ageDays = typeof opts.ageDays === "number" ? opts.ageDays : -1;
  var onLater = typeof opts.onLater === "function" ? opts.onLater : function () {};
  var onDone = typeof opts.onDone === "function" ? opts.onDone : function () {};

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // navigator.clipboard is blocked in some Script Lab iframe contexts, so
  // the textarea path is a real fallback for a known boundary, not a
  // bug-paver. When BOTH fail the URL is left selected and the button says
  // so — never a "Copied!" that didn't happen.
  function copyText(text) {
    function viaTextarea() {
      return new Promise(function (resolve, reject) {
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.cssText = "position:fixed;left:-9999px;opacity:0;";
        document.body.appendChild(ta);
        ta.select();
        var ok = false;
        try { ok = document.execCommand("copy"); } catch (_e) { ok = false; }
        document.body.removeChild(ta);
        if (ok) resolve(); else reject(new Error("clipboard blocked"));
      });
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(viaTextarea);
    }
    return viaTextarea();
  }

  var ov = document.createElement("div");
  ov.className = "_eli3_kc_overlay";
  ov.style.cssText =
    "position:fixed; inset:0; z-index:9650;" +
    "background:rgba(8,17,28,0.58);" +
    "display:flex; align-items:center; justify-content:center;" +
    "padding:14px; box-sizing:border-box;" +
    "font-family:Inter, system-ui, sans-serif;";

  var STEP_NUM =
    "flex:0 0 20px; height:20px; background:#0f172a; color:#f8fafc;" +
    "display:flex; align-items:center; justify-content:center;" +
    "font-size:11px; font-weight:800; border-radius:50%;";
  var STEP_TXT = "font-size:12.5px; color:#243141; line-height:1.55;";

  var ageLine = ageDays > 0
    ? "Published " + ageDays + (ageDays === 1 ? " day" : " days") + " ago."
    : "";

  // "X (Admin) or Y (Assistant to the Admin)" — falls back to the generic
  // phrasing when the marker names nobody, rather than an empty sentence.
  var contactsHtml = (function () {
    var list = Array.isArray(latest.adminContacts) ? latest.adminContacts : [];
    if (!list.length) return "your ELI admin";
    var parts = list.map(function (c) {
      return '<b style="color:#334155;">' + esc(c.name) + '</b>' +
        (c.role ? ' <span style="color:#94a3b8;">(' + esc(c.role) + ')</span>' : "");
    });
    if (parts.length === 1) return parts[0];
    return parts.slice(0, -1).join(", ") + " or " + parts[parts.length - 1];
  })();

  var card = document.createElement("div");
  card.className = "_eli3_kc_card";
  card.style.cssText =
    "width:min(460px, 100%); max-height:calc(100vh - 28px);" +
    "display:flex; flex-direction:column; background:#ffffff;" +
    "border:1px solid #c9a227; box-shadow:0 18px 50px rgba(8,17,28,0.4);";

  card.innerHTML =
    // Header
    '<div style="flex:0 0 auto; background:#0f172a; padding:14px 16px;">' +
      '<div style="display:flex; align-items:center; gap:9px;">' +
        '<span style="font-size:17px;">⚡</span>' +
        '<span style="font-size:14.5px; font-weight:800; color:#f8fafc; letter-spacing:.2px;">' +
          'ELI OS update needed</span>' +
      '</div>' +
      '<div style="font-size:11px; color:#94a3b8; margin-top:5px; line-height:1.5;">' +
        'Running <b style="color:#e2e8f0;">' + esc(current) + '</b><br>' +
        'Latest &nbsp;<b style="color:#f2d866;">' + esc(latest.version) + '</b>' +
        (ageLine ? ' <span style="color:#64748b;">· ' + esc(ageLine) + '</span>' : '') +
      '</div>' +
    '</div>' +

    // Body
    '<div style="flex:1 1 auto; overflow-y:auto; padding:15px 16px;">' +
      // Lead with the rarity. Seeing this for the first time, the natural
      // read is "something is broken" — it isn't, and saying so up front
      // costs one sentence.
      '<div style="display:flex; align-items:center; gap:7px; margin-bottom:10px;">' +
        '<span style="font-size:9px; font-weight:800; color:#166534; background:#dcfce7;' +
          'border:1px solid #86efac; padding:3px 8px; letter-spacing:1px;">RARE</span>' +
        '<span style="font-size:11.5px; color:#475569; font-weight:600;">' +
          'A few times a year, not a weekly chore.</span>' +
      '</div>' +
      '<div style="' + STEP_TXT + ' margin-bottom:13px;">' +
        'Nothing is wrong. ELI\'s tools update themselves quietly in the ' +
        'background — but the <b>ELI OS</b> they all run on is installed as a ' +
        'Script Lab snippet, and that one can only be replaced by hand. ' +
        'It takes about two minutes.' +
      '</div>' +

      (latest.notes
        ? '<div style="border-left:3px solid #c9a227; background:#fffdf5; padding:9px 11px;' +
            'margin-bottom:13px; font-size:12px; color:#5c4708; line-height:1.55;">' +
            esc(latest.notes) + '</div>'
        : '') +

      '<div style="font-size:9px; font-weight:800; color:#90a4ae; text-transform:uppercase;' +
        'letter-spacing:1.4px; margin-bottom:9px;">How to update</div>' +

      '<div style="display:flex; gap:9px; align-items:flex-start; margin-bottom:10px;">' +
        '<div style="' + STEP_NUM + '">1</div>' +
        '<div style="' + STEP_TXT + '">In Script Lab, open this snippet and ' +
          '<b>delete it</b>. Leaving the old one behind is what causes two ' +
          'copies to fight over the taskpane.</div>' +
      '</div>' +
      '<div style="display:flex; gap:9px; align-items:flex-start; margin-bottom:10px;">' +
        '<div style="' + STEP_NUM + '">2</div>' +
        '<div style="' + STEP_TXT + '">Choose <b>Import</b> and paste the URL below.</div>' +
      '</div>' +
      '<div style="display:flex; gap:9px; align-items:flex-start; margin-bottom:13px;">' +
        '<div style="' + STEP_NUM + '">3</div>' +
        '<div style="' + STEP_TXT + '">Run it. Your tools, settings and trophies ' +
          'are stored separately and carry over untouched.</div>' +
      '</div>' +

      '<div style="display:flex; gap:0; border:1px solid #cbd5e1;">' +
        '<input data-kc-url readonly value="' + esc(latest.importUrl) + '" ' +
          'style="flex:1 1 auto; min-width:0; border:0; padding:9px 10px;' +
          'font:600 11px/1.3 ui-monospace, Consolas, monospace; color:#0f172a;' +
          'background:#f8fafc; outline:none;">' +
        '<button data-kc-copy style="flex:0 0 auto; border:0; border-left:1px solid #cbd5e1;' +
          'padding:0 15px; cursor:pointer; background:#c9a227; color:#1a1a1a;' +
          'font:800 11px/1 Inter, sans-serif; letter-spacing:.4px;">COPY</button>' +
      '</div>' +
    '</div>' +

    // Footer
    '<div style="flex:0 0 auto; border-top:1px solid #e2e8f0; background:#f8fafc;">' +
    '<div style="padding:10px 16px 0; font-size:11.5px; color:#64748b; line-height:1.5;">' +
      'Anything unclear, or the import doesn\'t take? Contact ' + contactsHtml +
      '. No rush — finish what you\'re in the middle of first if you\'d rather.' +
    '</div>' +
    '<div style="display:flex; gap:8px; padding:12px 16px;">' +
      '<button data-kc-later style="flex:1; height:34px; cursor:pointer;' +
        'background:linear-gradient(to bottom,#ffffff 0%,#eef2f7 100%);' +
        'border:1px solid #cbd5e1; color:#334155;' +
        'font:700 12px/1 Inter, sans-serif;">Remind me next time</button>' +
      '<button data-kc-done style="flex:1; height:34px; cursor:pointer;' +
        'background:#0f172a; border:1px solid #0f172a; color:#f8fafc;' +
        'font:700 12px/1 Inter, sans-serif;">Done — don\'t ask again</button>' +
    '</div></div>';

  ov.appendChild(card);
  document.body.appendChild(ov);

  function close(cb) {
    if (ov.parentNode) ov.parentNode.removeChild(ov);
    cb();
  }

  var urlEl = card.querySelector("[data-kc-url]");
  var copyBtn = card.querySelector("[data-kc-copy]");
  copyBtn.onclick = function () {
    copyText(latest.importUrl).then(function () {
      copyBtn.textContent = "COPIED";
      copyBtn.style.background = "#15803d";
      copyBtn.style.color = "#f0fdf4";
      setTimeout(function () {
        copyBtn.textContent = "COPY";
        copyBtn.style.background = "#c9a227";
        copyBtn.style.color = "#1a1a1a";
      }, 1600);
    }).catch(function () {
      // Say what actually happened and leave the text selected.
      try { urlEl.focus(); urlEl.select(); } catch (_e) {}
      copyBtn.textContent = "PRESS ⌘/CTRL+C";
      copyBtn.style.background = "#7f1d1d";
      copyBtn.style.color = "#fee2e2";
    });
  };
  card.querySelector("[data-kc-later]").onclick = function () { close(onLater); };
  card.querySelector("[data-kc-done]").onclick = function () { close(onDone); };

  return ov;
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["kernel_check"];
  if (!bundle) return;
  var parse = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckParse;
  var compare = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckCompare;
  var age = bundle._eliEngineFns && bundle._eliEngineFns.kernelCheckAge;
  var render = bundle._eliViewFns && bundle._eliViewFns.renderKernelUpdate;
  if (!parse || !compare || !age || !render) {
    eli.log.event("tool", "kernel_check_init_missing_fns", {
      parse: !!parse, compare: !!compare, age: !!age, render: !!render,
    });
    return;
  }

  var MARKER_URL = "https://cdn.jsdelivr.net/gh/apndrewn/eli-data@main/kernel-latest.json";
  var DISMISS_KEY = "kernel_check_dismissed";
  // The dashboard paints first; an overlay racing it reads as a crash.
  var SHOW_DELAY_MS = 2500;
  var _open = false;

  // jsdelivr serves a cold 404 for up to a minute after a push and caches
  // aggressively afterwards. Same fallback eli-admin uses for overrides.
  function _rawFallbackUrl(u) {
    var m = /^https:\/\/cdn\.jsdelivr\.net\/gh\/([^/]+)\/([^/@]+)@([^/]+)\/(.+)$/.exec(u || "");
    return m ? ("https://raw.githubusercontent.com/" + m[1] + "/" + m[2] + "/" + m[3] + "/" + m[4]) : null;
  }

  function _fetchMarker() {
    if (typeof navigator !== "undefined" && navigator.onLine === false) {
      return Promise.resolve(null);
    }
    if (typeof fetch === "undefined") return Promise.resolve(null);
    function _try(u, isFallback) {
      var busted = u + (u.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
      return fetch(busted, { cache: "no-store" }).then(function (res) {
        if (!res.ok) {
          if (!isFallback) {
            var raw = _rawFallbackUrl(u);
            if (raw) return _try(raw, true);
          }
          throw new Error("marker fetch failed: " + res.status);
        }
        return res.json();
      });
    }
    return _try(MARKER_URL, false).catch(function (e) {
      // Not silent: a marker we can never read means this tool is dead
      // weight, and that should be discoverable rather than invisible.
      eli.log.event("tool", "kernel_check_fetch_failed", { msg: e && e.message });
      return null;
    });
  }

  function _dismissed() {
    return eli.storage.get("config", DISMISS_KEY)
      .then(function (row) { return (row && row.value) ? String(row.value) : null; })
      .catch(function () { return null; });
  }

  function _markDismissed(version) {
    return eli.storage.put("config", { key: DISMISS_KEY, value: version })
      .catch(function (e) {
        // A failed write means the notice returns every boot — worth seeing.
        eli.log.event("tool", "kernel_check_dismiss_write_failed", { msg: e && e.message });
      });
  }

  function _show(latest, verdict) {
    if (_open) return;
    _open = true;
    render({
      latest: latest,
      current: eli.kernelVersion || "unknown",
      ageDays: age(latest.builtAt, Date.now()),
      onLater: function () { _open = false; },
      onDone: function () { _open = false; _markDismissed(latest.version); },
    });
    eli.log.event("tool", "kernel_check_notice_shown", { reason: verdict.reason });
  }

  // force: skip the per-version dismissal (the tile re-opens on demand).
  function _check(force) {
    if (_open) return Promise.resolve();
    return _fetchMarker().then(function (raw) {
      var latest = parse(raw);
      if (!latest) {
        if (force) showToast("No ELI OS version has been published yet.", "info");
        return;
      }
      var verdict = compare(eli.kernelVersion, latest);
      if (verdict.state !== "behind") {
        if (force) {
          showToast(verdict.state === "current"
            ? "ELI OS is up to date (" + latest.version + ")."
            : "ELI OS " + verdict.state + " — " + verdict.reason, "ok");
        }
        return;
      }
      if (force) return _show(latest, verdict);
      return _dismissed().then(function (seen) {
        if (seen === latest.version) return;
        setTimeout(function () { _show(latest, verdict); }, SHOW_DELAY_MS);
      });
    });
  }

  // Fetched once per session — the fleet view asks for it per render.
  var _latestCache = null;

  eli.register({
    tile: { app_kernel_check: function () { _check(true); } },
    kernel_check: {
      open: function () { _check(true); },
      check: function () { return _check(false); },
      // For admin_fleet's kernel view. Exposing the marker and the
      // comparison rather than letting callers reimplement it is what stops
      // the fleet table and the user's own notice from disagreeing.
      latest: function (force) {
        if (_latestCache && !force) return Promise.resolve(_latestCache);
        return _fetchMarker().then(function (raw) {
          _latestCache = parse(raw);
          return _latestCache;
        });
      },
      verdict: function (version, latest) { return compare(version, latest); },
    },
  });

  _check(false);
}

jsonTools.css:
/* tools/kernel_check/style.css
   Keyframes only — everything else is inlined on the element for
   guaranteed paint (taskpane_v3.css is the only sheet the runtime loads). */

._eli3_kc_overlay { animation: _eli3_kc_fade 160ms ease-out; }
._eli3_kc_card { animation: _eli3_kc_rise 220ms cubic-bezier(.2,.8,.3,1); }

@keyframes _eli3_kc_fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes _eli3_kc_rise {
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to   { opacity: 1; transform: none; }
}
